(()=>{const l={zh:{home:'首页',tools:'AI 工具',history:'历史',projects:'项目',account:'账户'},en:{home:'Home',tools:'AI Tools',history:'History',projects:'Projects',account:'Account'}},g=()=>document.documentElement.lang==='zh-CN'?'zh':'en',s=()=>{const a=/account(?:\.html)?$/.test(location.pathname),v=new URLSearchParams(location.search).get('view')||'account',h=location.hash;document.querySelectorAll('.mobile-app-nav').forEach(n=>n.querySelectorAll('[data-mobile-destination]').forEach(x=>{const d=x.dataset.mobileDestination;x.textContent=l[g()][d];const c=a?(d===v||(d==='account'&&v==='account')):(d==='tools'?h==='#discover':d==='home'&&h!=='#discover');x.classList.toggle('active',c);x.toggleAttribute('aria-current',c)}))};s();window.addEventListener('hashchange',s);new MutationObserver(s).observe(document.documentElement,{attributes:true,attributeFilter:['lang']})})();
